<?php
session_start(); require_once('check-login.php'); require_once('task-scheduler-utils.php'); task_scheduler_ensure_tables($con);
if(!(isset($_SESSION['ACCESSLEVEL'],$_SESSION['SYSTEMTYPE'])&&$_SESSION['ACCESSLEVEL']==='user'&&$_SESSION['SYSTEMTYPE']==='Teacher')){header('location:index.php');exit();}
$teacherId=(string)$_SESSION['USERID'];$teacherEsc=mysqli_real_escape_string($con,$teacherId);
$rows=array();$sql="SELECT t.title,t.dueat,ce.class_name,sub.subject,s.response,s.submittedat,s.status AS submission_status,CONCAT_WS(' ',NULLIF(TRIM(u.firstname),''),NULLIF(TRIM(u.othernames),''),NULLIF(TRIM(u.surname),'')) student_name FROM tblteachertasksubmission s INNER JOIN tblteachertask t ON t.taskid=s.taskid INNER JOIN tblclassentry ce ON ce.class_entryid=t.classid INNER JOIN tblsubjectclassification sc ON sc.classificationid=t.classificationid INNER JOIN tblsubject sub ON sub.subjectid=sc.subjectid LEFT JOIN tblsystemuser u ON u.userid=s.studentid WHERE t.teacherid='$teacherEsc' ORDER BY s.submittedat DESC LIMIT 150";$res=@mysqli_query($con,$sql);if($res){while($row=mysqli_fetch_array($res,MYSQLI_ASSOC)){$rows[]=$row;}}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Task Submissions</title><?php include('links.php'); ?><link rel="stylesheet" href="css/task-scheduler.css"></head><body class="task-page"><main class="task-shell"><a class="task-back" href="teacher-page.php"><i class="fa fa-arrow-left"></i> Teacher dashboard</a><section class="task-hero"><div><span>Submission tracker</span><h1>Student task submissions</h1><p>Review returned work, see exactly when it was sent, and quickly spot late submissions.</p></div><i class="fa fa-inbox"></i></section><section class="task-list"><div class="task-section-heading"><div><span>Recent work</span><h2>All returned tasks</h2></div><p><?php echo count($rows); ?> submission<?php echo count($rows)===1?'':'s'; ?></p></div><?php if(count($rows)>0){ ?><div class="task-submission-list"><?php foreach($rows as $row){?><article class="task-submission-row"><div class="task-submission-row__avatar"><?php echo task_scheduler_escape(strtoupper(substr(trim($row['student_name'])?:'S',0,1))); ?></div><div class="task-submission-row__body"><strong><?php echo task_scheduler_escape(trim($row['student_name'])?:'Student'); ?></strong><span class="task-state task-state--<?php echo $row['submission_status']==='late'?'overdue':'submitted'; ?>"><?php echo $row['submission_status']==='late'?'Submitted late':'Submitted on time'; ?></span><p><b><?php echo task_scheduler_escape($row['title']); ?></b> · <?php echo task_scheduler_escape($row['subject'].' · '.$row['class_name']); ?></p><p><?php echo nl2br(task_scheduler_escape($row['response'])); ?></p><small><?php echo task_scheduler_escape(task_scheduler_due_label($row['submittedat'])); ?></small></div></article><?php } ?></div><?php }else{ ?><div class="task-empty"><i class="fa fa-inbox"></i><strong>No returned work yet</strong><p>Student responses will appear here once they submit a scheduled task.</p></div><?php } ?></section></main></body></html>
